class Solution { private fun gcd(aInput:Int,bInput:Int):Int{var a=aInput;var b=bInput;while(b!=0){val next=a%b;a=b;b=next};return a}fun minOperations(nums:IntArray):Int{val ones=nums.count{it==1};if(ones>0)return nums.size-ones;var best=Int.MAX_VALUE;for(left in nums.indices){var value=0;for(right in left until nums.size){value=gcd(value,nums[right]);if(value==1){best=minOf(best,right-left+1);break}}};return if(best==Int.MAX_VALUE)-1 else best+nums.size-2} }
